import { Component, h, Prop, Element, Host } from '@stencil/core';
import classnames from 'classnames';
import { BtnSize } from '../../ks-button/types';

const prefix = 'skeleton-button';

@Component({
  tag: 'ks-skeleton-button',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSkeletonButton {
  ['x-name'] = 'ks-skeleton-button';
  @Element() el!: HTMLKsSkeletonButtonElement;
  /** The size of the skeleton button. */
  @Prop() size: BtnSize = 'md';

  render() {
    // const cls = classnames('ks-skeleton', prefix, `${prefix}`);
    return (
      <Host class="KsSkeletonButton" aria-hidden="true">
        <div class={classnames(prefix, `${prefix}--${this.size}`)}></div>
      </Host>
    );
  }
}
